head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('wq_uuid_2_calendar_picker_cell_0').innerText == '2027';
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_2_img').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_2_calendar_picker_header_next_entity').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
